import { createSignal } from "solid-js";
const [, setN] = createSignal(0);
export function bump() { setN(1); }
export function bumpNow() { setN(1); }
export const store = { get bumped() { setN(1); return 1; } };
export function Bump() { setN(1); return "b"; }
export function SetBy(props) { props.set(1); return "s"; }
export function reset() { setN(0); }
export function Label() { return "x"; }
